# Parse JSON notebook files to extract code and information
def parse_notebook(file_path):
    """Parse Jupyter notebook JSON and extract relevant information"""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            notebook = json.load(f)

        info = {
            'cells': [],
            'markdown_content': [],
            'code_content': [],
            'api_endpoints': [],
            'file_contents': {},
            'descriptions': []
        }

        for cell in notebook.get('cells', []):
            cell_type = cell.get('cell_type', '')
            source = cell.get('source', [])

            if isinstance(source, list):
                content = ''.join(source)
            else:
                content = source

            info['cells'].append({
                'type': cell_type,
                'content': content
            })

            if cell_type == 'markdown':
                info['markdown_content'].append(content)
                # Extract descriptions
                if any(keyword in content.lower() for keyword in ['tugas', 'komponen', 'struktur', 'api']):
                    info['descriptions'].append(content)

            elif cell_type == 'code':
                info['code_content'].append(content)

                # Look for file creation patterns
                if 'write(' in content or 'open(' in content:
                    lines = content.split('\n')
                    for line in lines:
                        if 'with open(' in line and '.js' in line:
                            # Extract API endpoint filename
                            try:
                                filename = line.split('"')[1] if '"' in line else line.split("'")[1]
                                if filename.endswith('.js'):
                                    info['api_endpoints'].append(filename)
                            except:
                                pass

        return info
    except Exception as e:
        print(f"Error parsing {file_path}: {str(e)}")
        return None

