# Create directory structure
def create_comprehensive_structure(base_path, structure):
    """Create the complete directory structure"""
    created_dirs = []

    for main_dir, subdirs in structure.items():
        main_path = os.path.join(base_path, main_dir)
        os.makedirs(main_path, exist_ok=True)
        created_dirs.append(main_dir)
        print(f"📁 Created: {main_dir}/")

        if isinstance(subdirs, dict):
            for subdir, subsubdirs in subdirs.items():
                sub_path = os.path.join(main_path, subdir)
                os.makedirs(sub_path, exist_ok=True)
                created_dirs.append(f"{main_dir}/{subdir}")
                print(f"  📁 Created: {main_dir}/{subdir}/")

                for subsubdir in subsubdirs:
                    subsub_path = os.path.join(sub_path, subsubdir)
                    os.makedirs(subsub_path, exist_ok=True)
                    created_dirs.append(f"{main_dir}/{subdir}/{subsubdir}")
                    print(f"    📁 Created: {main_dir}/{subdir}/{subsubdir}/")
        else:
            for subdir in subdirs:
                sub_path = os.path.join(main_path, subdir)
                os.makedirs(sub_path, exist_ok=True)
                created_dirs.append(f"{main_dir}/{subdir}")
                print(f"  📁 Created: {main_dir}/{subdir}/")

    return created_dirs

